      { question: "0,24 · 50 = ?", options: ["12", "1,2", "120", "0,12"], answer: "12", explain: "50 = 5 · 10. 0,24 · 5 = 1,2; so'ng 10 ga: vergul 1 xona o'ngga — <b>12</b>." },
      { question: "8,1 : 90 = ?", options: ["0,09", "0,9", "9", "0,009"], answer: "0,09", explain: "90 = 9 · 10. 8,1 : 9 = 0,9; so'ng 10 ga bo'lamiz: vergul 1 xona chapga — <b>0,09</b>." },
      { question: "1 ta konvert 0,6 ming so'm. 500 ta konvert necha ming so'm?", options: ["300 ming", "30 ming", "3000 ming", "3 ming"], answer: "300 ming", explain: "0,6 · 500 = 0,6 · 5 · 100 = 3 · 100 = <b>300</b> ming." },
      { question: "Bog'da 2,8 t olma terildi va 70 ta yashikka teng joylandi. Bir yashikda necha tonna?", options: ["0,04 t", "0,4 t", "4 t", "0,004 t"], answer: "0,04 t", explain: "2,8 : 70: 2,8 : 7 = 0,4; : 10 — <b>0,04 t</b> (40 kg)." },
      { question: "6,4 : 800 = ?", options: ["0,008", "0,08", "0,8", "0,0008"], answer: "0,008", explain: "800 = 8 · 100. 6,4 : 8 = 0,8; so'ng 100 ga bo'lamiz: vergul 2 xona chapga — <b>0,008</b>." },
      { question: "0,09 · 700 = ?", options: ["63", "6,3", "630", "0,63"], answer: "63", explain: "700 = 7 · 100. 0,09 · 7 = 0,63; so'ng 100 ga: vergul 2 xona o'ngga — <b>63</b>." }
